window.kbPageData["views/entry/k-7d3e3551e4625a5e"] = {"key":"entry/k-7d3e3551e4625a5e","state":{"route":"entry/k-7d3e3551e4625a5e"},"node":{"id":"k-7d3e3551e4625a5e","mode":"k","title":"危险废物分类贮存、标识与防漏","type":"制度与规则","domain":"生态环境","reading":"","intro":"","priority":100,"aliases":["危险废物分类贮存、标识与防渗漏"],"qs":["国考 2025 行政执法 申论#4"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"按西瑞药业材料所述的贮存做法，库管人员应将不同种类的危险废物分类打包、贴签并分区存放。仓库设置警示标志、标识牌和防漏设施。","review":{"definition":"按西瑞药业材料所述的贮存做法，库管人员应将不同种类的危险废物分类打包、贴签并分区存放。仓库设置警示标志、标识牌和防漏设施。","explanation":"申论第4题中，仓库外有警示标志和标识牌，库内设围堰、收集沟并采取独立防漏措施，可写为贮存管理成效。现场发现两袋危废未贴标签，周围还有散落的废包装物，具体暴露出临时收存环节的贴签和分类包装漏洞，对应入库时落实分类打包、贴签的建议。","references":[],"evidence":"有两袋危险废物没有贴标签，周围还零星散落了一些废包装物。","disposition":"题内说明","basis":"据原题和解析编释。"}},"questions":{"国考 2025 行政执法 申论#4":{"paper":"国考 2025 行政执法 申论","n":4,"mod":"申论","src":["dbb2469ea58338709f40.pdf",4],"asrc":["d1fc3fe21ef6ae3b1ae6.pdf",3],"card":"e9b26cf35f72426e9b032d20","links":[{"id":"k-7d3e3551e4625a5e","role":"直接考查","why":"分类包装、标识和防渗漏设施是评价危废贮存成效、识别现场管理漏洞的依据。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-7d3e3551e4625a5e":[["国考 2025 行政执法 申论#4"]]}};
